   131→function isNavigationState(value: unknown): value is TabNavigationState {
   132→  if (!value || typeof value !== "object") return false;
   133→  const candidate = value as Partial<TabNavigationState>;
   134→  return Boolean(candidate.location && Array.isArray(candidate.breadcrumbStack));
   135→}
   136→
   137→function isPersistedPageTab(value: unknown): value is PageTab {
   138→  if (!value || typeof value !== "object") return false;
   139→  const candidate = value as Partial<PageTab>;
   140→  return typeof candidate.id === "string" && Array.isArray(candidate.navigationHistory);
   141→}
   142→
   143→function isPersistedSnapshot(value: unknown): value is ClosedTabSnapshot {
   144→  if (!value || typeof value !== "object") return false;
   145→  const candidate = value as Partial<ClosedTabSnapshot>;
   146→  return (
   147→    isPersistedPageTab(candidate.tab) &&
   148→    typeof candidate.originIndex === "number" &&
   149→    typeof candidate.closedAt === "number"
   150→  );
   151→}
