// apps/desktop/src/navigation/tab-navigation.ts
import type { BreadcrumbStackItem } from "./breadcrumb-builder";
import type { TabNavigationState } from "@/stores/tab-store";

/**
 * Create a new TabNavigationState from a URL and breadcrumb stack.
 */
export function createTabNavigationState(
  url: string,
  breadcrumbStack: BreadcrumbStackItem[],
  patch?: Partial<TabNavigationState>,
): TabNavigationState {
  return { url, breadcrumbStack, ...patch };
}

import { create } from "zustand";
import { persist } from "zustand/middleware";
import { registry } from "@/navigation/route-registry";
import { buildColdStartBreadcrumb } from "@/navigation/breadcrumb-builder";
import type { BreadcrumbStackItem } from "@/navigation/breadcrumb-builder";
import { locationToUrl } from "@/navigation/navigation-meta";
import type { DesktopLocation } from "@/navigation/navigation-meta";

// ─── TabNavigationState (URL-based) ─────────────────────────────────────────

export interface TabNavigationState {
  url: string;
  breadcrumbStack: BreadcrumbStackItem[];
  activeNodeId?: string;
  activeIndexPath?: string[];
}

export type PageViewMode = "skill" | "page";

export interface PageTab {
  id: string;
  pinned: boolean;
  historyIndex: number;
  navigationHistory: TabNavigationState[];
  viewMode?: PageViewMode;
}

export interface ClosedTabSnapshot {
  tab: PageTab;
  closedAt: number;
  originIndex: number;
}

interface TabState {
  tabs: PageTab[];
  activeTabId: string | null;
  recentlyClosedTabs: ClosedTabSnapshot[];
}

interface OpenTabInput {
  pinned?: boolean;
  viewMode?: PageViewMode;
  navigationState: TabNavigationState;
}

export interface TabViewModel extends PageTab {
  currentState: TabNavigationState | null;
  currentUrl: string | null;
  label: string;
  icon?: BreadcrumbStackItem["icon"];
  descriptorId?: string;
  meta?: BreadcrumbStackItem["meta"];
  url: string | null;
}

interface TabActions {
  openTab: (tab: OpenTabInput) => string;
  closeTab: (tabId: string) => void;
  closeOtherTabs: (tabId: string) => void;
  closeTabsToRight: (tabId: string) => void;
  setActiveTab: (tabId: string) => void;
  pinTab: (tabId: string) => void;
  unpinTab: (tabId: string) => void;
  setViewMode: (tabId: string, mode: PageViewMode) => void;
  moveTab: (fromIndex: number, toIndex: number) => void;
  navigate: (tabId: string, url: string) => void;
  pushNavigation: (tabId: string, url: string, leaf: BreadcrumbStackItem) => void;
  replaceNavigation: (tabId: string, url: string, leaf: BreadcrumbStackItem) => void;
  resetNavigation: (tabId: string, url: string, stack: BreadcrumbStackItem[]) => void;
  replaceLocation: (tabId: string, next: TabNavigationState) => void;
  pushLocation: (tabId: string, next: TabNavigationState) => void;
  insertHistoryBeforeCurrent: (tabId: string, state: TabNavigationState) => void;
  jumpToHistory: (tabId: string, historyIndex: number) => void;
  goBack: (tabId: string) => void;
  goForward: (tabId: string) => void;
  canGoBack: (tabId: string) => boolean;
  canGoForward: (tabId: string) => boolean;
  getCurrentUrl: (tabId: string) => string | null;
  getCurrentNavigationState: (tabId: string) => TabNavigationState | null;
  findHistoryEntryByUrl: (tabId: string, url: string) => number;
  closeAllTabs: () => void;
  duplicateTab: (tabId: string) => string | null;
  reopenClosedTab: () => string | null;
  restoreTab: (tab: PageTab) => void;
}

const generateTabId = () =>
  `tab-${Date.now()}-${Math.random().toString(36).slice(2, 11)}`;
const MAX_RECENTLY_CLOSED_TABS = 20;
export const TAB_STORE_STORAGE_KEY = "viben-tab-store-v2";
const TAB_STORE_VERSION = 2;

function findLastPinnedIndex(tabs: PageTab[]): number {
  for (let index = tabs.length - 1; index >= 0; index -= 1) {
    if (tabs[index].pinned) {
      return index;
    }
  }
  return -1;
}

function buildStateFromUrl(url?: string): TabNavigationState {
  const targetUrl = url ?? "/documents";
  const stack = buildColdStartBreadcrumb(targetUrl);
  return { url: targetUrl, breadcrumbStack: stack };
}

function isNavigationState(value: unknown): value is TabNavigationState {
  if (!value || typeof value !== "object") return false;
  const candidate = value as Partial<TabNavigationState>;
  return typeof candidate.url === "string" && Array.isArray(candidate.breadcrumbStack);
}

function isPersistedPageTab(value: unknown): value is PageTab {
  if (!value || typeof value !== "object") return false;
  const candidate = value as Partial<PageTab>;
  return typeof candidate.id === "string" && Array.isArray(candidate.navigationHistory);
}

function isPersistedSnapshot(value: unknown): value is ClosedTabSnapshot {
  if (!value || typeof value !== "object") return false;
  const candidate = value as Partial<ClosedTabSnapshot>;
  return (
    isPersistedPageTab(candidate.tab) &&
    typeof candidate.originIndex === "number" &&
    typeof candidate.closedAt === "number"
  );
}

function normalizeTab(tab: PageTab): PageTab {
  const navigationHistory = tab.navigationHistory.filter(isNavigationState);
  const safeHistory = navigationHistory.length > 0 ? navigationHistory : [buildStateFromUrl("/documents")];
  const historyIndex = Math.min(
    Math.max(tab.historyIndex ?? safeHistory.length - 1, 0),
    safeHistory.length - 1
  );

  return {
    id: tab.id,
    pinned: Boolean(tab.pinned),
    historyIndex,
    navigationHistory: safeHistory,
    viewMode: tab.viewMode,
  };
}

function normalizeSnapshot(snapshot: ClosedTabSnapshot): ClosedTabSnapshot {
  return {
    tab: normalizeTab(snapshot.tab),
    originIndex: snapshot.originIndex,
    closedAt: snapshot.closedAt,
  };
}

export function mergePersistedTabState(
  persisted: Partial<TabState> | undefined,
  current: TabState
): TabState {
  const tabs = (persisted?.tabs ?? []).filter(isPersistedPageTab).map(normalizeTab);
  const tabIds = new Set(tabs.map((tab) => tab.id));
  const activeTabId =
    persisted?.activeTabId && tabIds.has(persisted.activeTabId)
      ? persisted.activeTabId
      : tabs[0]?.id ?? null;

  return {
    ...current,
    tabs,
    activeTabId,
    recentlyClosedTabs: (persisted?.recentlyClosedTabs ?? [])
      .filter(isPersistedSnapshot)
      .map(normalizeSnapshot),
  };
}

function cloneTabWithNewId(tab: PageTab, overrides?: Partial<PageTab>): PageTab {
  return normalizeTab({
    ...normalizeTab(tab),
    ...overrides,
    id: generateTabId(),
  });
}

function createClosedSnapshot(tab: PageTab, originIndex: number): ClosedTabSnapshot {
  return {
    tab: normalizeTab(tab),
    originIndex,
    closedAt: Date.now(),
  };
}

function pushClosedSnapshots(
  stack: ClosedTabSnapshot[],
  snapshots: ClosedTabSnapshot[]
): ClosedTabSnapshot[] {
  if (snapshots.length === 0) {
    return stack;
  }

  return [...snapshots].reverse().concat(stack).slice(0, MAX_RECENTLY_CLOSED_TABS);
}

function restoreClosedTabIntoTabs(
  tabs: PageTab[],
  snapshot: ClosedTabSnapshot
): { tabs: PageTab[]; restoredTab: PageTab } {
  const restoredTab = cloneTabWithNewId(snapshot.tab);
  const nextTabs = [...tabs];
  const insertIndex = Math.max(0, Math.min(snapshot.originIndex, nextTabs.length));
  nextTabs.splice(insertIndex, 0, restoredTab);
  return { tabs: nextTabs, restoredTab };
}

export function getTabCurrentState(tab: PageTab): TabNavigationState | null {
  return tab.navigationHistory[tab.historyIndex] ?? null;
}

export function getTabCurrentLeaf(tab: PageTab): BreadcrumbStackItem | null {
  const current = getTabCurrentState(tab);
  return current?.breadcrumbStack[current.breadcrumbStack.length - 1] ?? null;
}

export function getTabUrl(tab: PageTab): string | null {
  const current = getTabCurrentState(tab);
  return current?.url ?? null;
}

export function getTabViewModel(tab: PageTab): TabViewModel {
  const currentState = getTabCurrentState(tab);
  const leaf = getTabCurrentLeaf(tab);
  const url = getTabUrl(tab);

  return {
    ...tab,
    currentState,
    currentUrl: url,
    label: leaf?.label ?? url ?? "Untitled",
    icon: leaf?.icon,
    descriptorId: leaf?.pattern,
    meta: leaf?.meta,
    url,
  };
}

function findHistoryEntryByUrlInHistory(
  navigationHistory: TabNavigationState[],
  historyIndex: number,
  url: string
): number {
  for (let index = historyIndex - 1; index >= 0; index -= 1) {
    if (navigationHistory[index].url === url) {
      return index;
    }
  }
  return -1;
}

// ─── Persist Migration ───────────────────────────────────────────────────────

interface LegacyTabNavigationState {
  location: DesktopLocation;
  breadcrumbStack: Array<{
    id: string;
    label: string;
    icon?: unknown;
    descriptorId?: string;
    sourceNodeId?: string;
    parentNodeId?: string;
    target?: {
      key: string;
      location: DesktopLocation;
      canonicalUrl: string;
    };
    meta?: Record<string, unknown>;
  }>;
  activeNodeId?: string;
  activeIndexPath?: string[];
}

function migrateLegacyNavigationState(legacy: LegacyTabNavigationState): TabNavigationState | null {
  // Convert location to URL
  let url: string;
  try {
    url = locationToUrl(legacy.location);
  } catch {
    return null;
  }

  // Validate URL is known in registry
  if (!registry.match(url)) {
    return null;
  }

  // Convert breadcrumb stack items (extract href from target, use new format)
  const breadcrumbStack: BreadcrumbStackItem[] = legacy.breadcrumbStack.map((item) => {
    const result: BreadcrumbStackItem = {
      id: item.id,
      label: item.label,
      icon: item.icon as BreadcrumbStackItem["icon"],
      href: item.target?.canonicalUrl,
      sourceNodeId: item.sourceNodeId,
      parentNodeId: item.parentNodeId,
      meta: item.meta as BreadcrumbStackItem["meta"],
    };
    return result;
  });

  return {
    url,
    breadcrumbStack,
    activeNodeId: legacy.activeNodeId,
    activeIndexPath: legacy.activeIndexPath,
  };
}

function isLegacyNavigationState(value: unknown): value is LegacyTabNavigationState {
  if (!value || typeof value !== "object") return false;
  const candidate = value as Record<string, unknown>;
  return (
    candidate.location !== undefined &&
    typeof candidate.location === "object" &&
    candidate.location !== null &&
    "kind" in (candidate.location as object) &&
    Array.isArray(candidate.breadcrumbStack)
  );
}

function migratePersistedState(persisted: Record<string, unknown>): Record<string, unknown> {
  const tabs = persisted.tabs;
  if (!Array.isArray(tabs)) return persisted;

  const migratedTabs = tabs.map((tab: unknown) => {
    if (!tab || typeof tab !== "object") return tab;
    const tabObj = tab as Record<string, unknown>;
    const history = tabObj.navigationHistory;
    if (!Array.isArray(history)) return tab;

    const migratedHistory: TabNavigationState[] = [];
    for (const entry of history) {
      // Already in new format
      if (isNavigationState(entry)) {
        migratedHistory.push(entry as TabNavigationState);
        continue;
      }
      // Legacy format
      if (isLegacyNavigationState(entry)) {
        const migrated = migrateLegacyNavigationState(entry);
        if (migrated) {
          migratedHistory.push(migrated);
        }
        // If migration returns null (invalid/unrecognized URL), drop the entry
        continue;
      }
      // Unknown format, drop
    }

    // Ensure at least one valid entry
    const safeHistory = migratedHistory.length > 0
      ? migratedHistory
      : [buildStateFromUrl("/workspace")];

    // Clamp historyIndex
    const oldIndex = typeof tabObj.historyIndex === "number" ? tabObj.historyIndex : safeHistory.length - 1;
    const historyIndex = Math.min(Math.max(oldIndex, 0), safeHistory.length - 1);

    return {
      ...tabObj,
      navigationHistory: safeHistory,
      historyIndex,
    };
  });

  // Also migrate recentlyClosedTabs
  const recentlyClosed = persisted.recentlyClosedTabs;
  let migratedClosed = recentlyClosed;
  if (Array.isArray(recentlyClosed)) {
    migratedClosed = recentlyClosed.map((snapshot: unknown) => {
      if (!snapshot || typeof snapshot !== "object") return snapshot;
      const snapObj = snapshot as Record<string, unknown>;
      const tab = snapObj.tab;
      if (!tab || typeof tab !== "object") return snapshot;
      const tabObj = tab as Record<string, unknown>;
      const history = tabObj.navigationHistory;
      if (!Array.isArray(history)) return snapshot;

      const migratedHistory: TabNavigationState[] = [];
      for (const entry of history) {
        if (isNavigationState(entry)) {
          migratedHistory.push(entry as TabNavigationState);
          continue;
        }
        if (isLegacyNavigationState(entry)) {
          const migrated = migrateLegacyNavigationState(entry);
          if (migrated) {
            migratedHistory.push(migrated);
          }
          continue;
        }
      }

      const safeHistory = migratedHistory.length > 0
        ? migratedHistory
        : [buildStateFromUrl("/workspace")];

      const oldIndex = typeof tabObj.historyIndex === "number" ? tabObj.historyIndex : safeHistory.length - 1;
      const historyIndex = Math.min(Math.max(oldIndex, 0), safeHistory.length - 1);

      return {
        ...snapObj,
        tab: {
          ...tabObj,
          navigationHistory: safeHistory,
          historyIndex,
        },
      };
    });
  }

  return {
    ...persisted,
    tabs: migratedTabs,
    recentlyClosedTabs: migratedClosed,
  };
}

// ─── Store ───────────────────────────────────────────────────────────────────

export const useTabStore = create<TabState & TabActions>()(
  persist(
    (set, get) => ({
      tabs: [],
      activeTabId: null,
      recentlyClosedTabs: [],

      openTab: (tabData) => {
        const id = generateTabId();
        const newTab = normalizeTab({
          id,
          pinned: tabData.pinned ?? false,
          navigationHistory: [tabData.navigationState],
          historyIndex: 0,
          viewMode: tabData.viewMode,
        });

        set((state) => ({
          tabs: [...state.tabs, newTab],
          activeTabId: id,
        }));

        return id;
      },

      closeTab: (tabId) => {
        set((state) => {
          const tabIndex = state.tabs.findIndex((tab) => tab.id === tabId);
          if (tabIndex === -1) return state;

          const recentlyClosedTabs = pushClosedSnapshots(
            state.recentlyClosedTabs,
            [createClosedSnapshot(state.tabs[tabIndex], tabIndex)]
          );
          const tabs = state.tabs.filter((tab) => tab.id !== tabId);
          let activeTabId = state.activeTabId;

          if (state.activeTabId === tabId) {
            if (tabs.length === 0) {
              activeTabId = null;
            } else if (tabIndex >= tabs.length) {
              activeTabId = tabs[tabs.length - 1].id;
            } else {
              activeTabId = tabs[tabIndex].id;
            }
          }

          return { tabs, activeTabId, recentlyClosedTabs };
        });
      },

      closeOtherTabs: (tabId) => {
        set((state) => {
          const snapshots = state.tabs
            .map((tab, index) => ({ tab, index }))
            .filter(({ tab }) => !tab.pinned && tab.id !== tabId)
            .map(({ tab, index }) => createClosedSnapshot(tab, index));

          return {
            tabs: state.tabs.filter((tab) => tab.pinned || tab.id === tabId),
            activeTabId: tabId,
            recentlyClosedTabs: pushClosedSnapshots(state.recentlyClosedTabs, snapshots),
          };
        });
      },

      closeTabsToRight: (tabId) => {
        set((state) => {
          const tabIndex = state.tabs.findIndex((tab) => tab.id === tabId);
          if (tabIndex === -1) return state;

          const snapshots = state.tabs
            .map((tab, index) => ({ tab, index }))
            .filter(({ tab, index }) => index > tabIndex && !tab.pinned)
            .map(({ tab, index }) => createClosedSnapshot(tab, index));
          const closingIds = new Set(snapshots.map((snapshot) => snapshot.tab.id));
          const tabs = state.tabs.filter((tab) => !closingIds.has(tab.id));
          const activeTabId = tabs.some((tab) => tab.id === state.activeTabId)
            ? state.activeTabId
            : tabId;

          return {
            tabs,
            activeTabId,
            recentlyClosedTabs: pushClosedSnapshots(state.recentlyClosedTabs, snapshots),
          };
        });
      },

      setActiveTab: (tabId) => {
        set({ activeTabId: tabId });
      },

      pinTab: (tabId) => {
        set((state) => {
          const tabIndex = state.tabs.findIndex((tab) => tab.id === tabId);
          if (tabIndex === -1) return state;

          const tab = state.tabs[tabIndex];
          if (tab.pinned) return state;

          const tabs = [...state.tabs];
          tabs.splice(tabIndex, 1);

          const insertIndex = findLastPinnedIndex(tabs) + 1;
          tabs.splice(insertIndex, 0, { ...tab, pinned: true });

          return { tabs };
        });
      },

      unpinTab: (tabId) => {
        set((state) => {
          const tabIndex = state.tabs.findIndex((tab) => tab.id === tabId);
          if (tabIndex === -1) return state;

          const tab = state.tabs[tabIndex];
          if (!tab.pinned) return state;

          const tabs = [...state.tabs];
          tabs.splice(tabIndex, 1);

          const insertIndex = findLastPinnedIndex(tabs) + 1;
          tabs.splice(insertIndex, 0, { ...tab, pinned: false });

          return { tabs };
        });
      },

      setViewMode: (tabId, mode) => {
        set((state) => ({
          tabs: state.tabs.map((tab) =>
            tab.id === tabId ? { ...tab, viewMode: mode } : tab
          ),
        }));
      },

      moveTab: (fromIndex, toIndex) => {
        set((state) => {
          if (
            fromIndex === toIndex ||
            fromIndex < 0 ||
            toIndex < 0 ||
            fromIndex >= state.tabs.length ||
            toIndex >= state.tabs.length
          ) {
            return state;
          }

          const tabs = [...state.tabs];
          const [moved] = tabs.splice(fromIndex, 1);
          tabs.splice(toIndex, 0, moved);
          return { tabs };
        });
      },

      navigate: (tabId, url) => {
        get().pushLocation(tabId, buildStateFromUrl(url));
      },

      pushNavigation: (tabId, url, leaf) => {
        const tab = get().tabs.find((entry) => entry.id === tabId);
        const current = tab ? getTabCurrentState(normalizeTab(tab)) : null;
        const currentStack = current?.breadcrumbStack ?? [];
        const nextState: TabNavigationState = {
          url,
          breadcrumbStack: [...currentStack, leaf],
        };
        get().pushLocation(tabId, nextState);
      },

      replaceNavigation: (tabId, url, leaf) => {
        const tab = get().tabs.find((entry) => entry.id === tabId);
        const current = tab ? getTabCurrentState(normalizeTab(tab)) : null;
        const currentStack = current?.breadcrumbStack ?? [];
        const nextState: TabNavigationState = {
          url,
          breadcrumbStack: [...currentStack.slice(0, -1), leaf],
        };
        get().pushLocation(tabId, nextState);
      },

      resetNavigation: (tabId, url, stack) => {
        const nextState: TabNavigationState = { url, breadcrumbStack: stack };
        get().pushLocation(tabId, nextState);
      },

      replaceLocation: (tabId, next) => {
        set((state) => ({
          tabs: state.tabs.map((tab) => {
            if (tab.id !== tabId) return tab;
            const current = normalizeTab(tab);
            const baseHistory = current.navigationHistory.slice(0, current.historyIndex);
            return normalizeTab({
              ...current,
              navigationHistory: [...baseHistory, next],
              historyIndex: baseHistory.length,
            });
          }),
        }));
      },

      pushLocation: (tabId, next) => {
        set((state) => ({
          tabs: state.tabs.map((tab) => {
            if (tab.id !== tabId) return tab;
            const current = normalizeTab(tab);
            const baseHistory = current.navigationHistory.slice(0, current.historyIndex + 1);
            return normalizeTab({
              ...current,
              navigationHistory: [...baseHistory, next],
              historyIndex: baseHistory.length,
            });
          }),
        }));
      },

      insertHistoryBeforeCurrent: (tabId, next) => {
        set((state) => ({
          tabs: state.tabs.map((tab) => {
            if (tab.id !== tabId) return tab;
            const current = normalizeTab(tab);
            const before = current.navigationHistory.slice(0, current.historyIndex);
            const fromCurrent = current.navigationHistory.slice(current.historyIndex);
            return normalizeTab({
              ...current,
              navigationHistory: [...before, next, ...fromCurrent],
              historyIndex: before.length,
            });
          }),
        }));
      },

      jumpToHistory: (tabId, historyIndex) => {
        set((state) => ({
          tabs: state.tabs.map((tab) => {
            if (tab.id !== tabId) return tab;
            const current = normalizeTab(tab);
            return normalizeTab({
              ...current,
              historyIndex,
            });
          }),
        }));
      },

      goBack: (tabId) => {
        set((state) => ({
          tabs: state.tabs.map((tab) => {
            if (tab.id !== tabId) return tab;
            const current = normalizeTab(tab);
            if (current.historyIndex <= 0) return current;
            return {
              ...current,
              historyIndex: current.historyIndex - 1,
            };
          }),
        }));
      },

      goForward: (tabId) => {
        set((state) => ({
          tabs: state.tabs.map((tab) => {
            if (tab.id !== tabId) return tab;
            const current = normalizeTab(tab);
            if (current.historyIndex >= current.navigationHistory.length - 1) {
              return current;
            }
            return {
              ...current,
              historyIndex: current.historyIndex + 1,
            };
          }),
        }));
      },

      canGoBack: (tabId) => {
        const tab = get().tabs.find((item) => item.id === tabId);
        return tab ? normalizeTab(tab).historyIndex > 0 : false;
      },

      canGoForward: (tabId) => {
        const tab = get().tabs.find((item) => item.id === tabId);
        if (!tab) return false;
        const current = normalizeTab(tab);
        return current.historyIndex < current.navigationHistory.length - 1;
      },

      getCurrentUrl: (tabId) => {
        const tab = get().tabs.find((item) => item.id === tabId);
        if (!tab) return null;
        const current = getTabCurrentState(normalizeTab(tab));
        return current?.url ?? null;
      },

      getCurrentNavigationState: (tabId) => {
        const tab = get().tabs.find((item) => item.id === tabId);
        return tab ? getTabCurrentState(normalizeTab(tab)) : null;
      },

      findHistoryEntryByUrl: (tabId, url) => {
        const tab = get().tabs.find((item) => item.id === tabId);
        if (!tab) return -1;
        const current = normalizeTab(tab);
        return findHistoryEntryByUrlInHistory(
          current.navigationHistory,
          current.historyIndex,
          url
        );
      },

      closeAllTabs: () => {
        set((state) => {
          const snapshots = state.tabs
            .map((tab, index) => ({ tab, index }))
            .filter(({ tab }) => !tab.pinned)
            .map(({ tab, index }) => createClosedSnapshot(tab, index));
          const tabs = state.tabs.filter((tab) => tab.pinned);
          return {
            tabs,
            activeTabId: tabs[0]?.id ?? null,
            recentlyClosedTabs: pushClosedSnapshots(state.recentlyClosedTabs, snapshots),
          };
        });
      },

      duplicateTab: (tabId) => {
        const state = get();
        const tabIndex = state.tabs.findIndex((tab) => tab.id === tabId);
        if (tabIndex === -1) return null;

        const duplicatedTab = cloneTabWithNewId(state.tabs[tabIndex], {
          pinned: false,
        });

        set((current) => {
          const tabs = [...current.tabs];
          tabs.splice(tabIndex + 1, 0, duplicatedTab);
          return {
            tabs,
            activeTabId: duplicatedTab.id,
          };
        });

        return duplicatedTab.id;
      },

      reopenClosedTab: () => {
        let restoredTabId: string | null = null;

        set((current) => {
          const [nextSnapshot, ...restSnapshots] = current.recentlyClosedTabs;
          if (!nextSnapshot) return current;

          const restored = restoreClosedTabIntoTabs(current.tabs, nextSnapshot);
          restoredTabId = restored.restoredTab.id;

          return {
            tabs: restored.tabs,
            activeTabId: restored.restoredTab.id,
            recentlyClosedTabs: restSnapshots,
          };
        });

        return restoredTabId;
      },

      restoreTab: (tab) => {
        const restoredTab = cloneTabWithNewId(tab);
        set((state) => ({
          tabs: [...state.tabs, restoredTab],
          activeTabId: restoredTab.id,
        }));
      },
    }),
    {
      name: TAB_STORE_STORAGE_KEY,
      version: TAB_STORE_VERSION,
      partialize: (state) => ({
        tabs: state.tabs,
        activeTabId: state.activeTabId,
        recentlyClosedTabs: state.recentlyClosedTabs,
      }),
      migrate: (persisted, version) => {
        if (version < TAB_STORE_VERSION) {
          return migratePersistedState(persisted as Record<string, unknown>);
        }
        return persisted;
      },
      merge: (persisted, current) => {
        return {
          ...current,
          ...mergePersistedTabState(
            persisted as Partial<TabState> | undefined,
            current
          ),
        };
      },
    }
  )
);

export const selectActiveTab = (state: TabState) =>
  state.tabs.find((tab) => tab.id === state.activeTabId) ?? null;

export const selectPinnedTabs = (state: TabState) =>
  state.tabs.filter((tab) => tab.pinned);

export const selectUnpinnedTabs = (state: TabState) =>
  state.tabs.filter((tab) => !tab.pinned);

import { beforeEach, describe, expect, it } from "vitest";
import type { BreadcrumbStackItem } from "@/navigation/breadcrumb-builder";
import {
  TAB_STORE_STORAGE_KEY,
  getTabCurrentLeaf,
  getTabCurrentState,
  getTabUrl,
  getTabViewModel,
  mergePersistedTabState,
  useTabStore,
  type ClosedTabSnapshot,
  type PageTab,
  type TabNavigationState,
} from "./tab-store";

const FORBIDDEN_PAGE_TAB_FIELDS = [
  "label",
  "icon",
  "descriptorId",
  "meta",
  "target",
  "sourceNodeId",
  "parentNodeId",
  "history",
] as const;

function leaf(
  id: string,
  label: string,
  href: string,
  meta?: BreadcrumbStackItem["meta"]
): BreadcrumbStackItem {
  return {
    id,
    label,
    href,
    meta,
  };
}

function state(url: string, stack: BreadcrumbStackItem[] = []): TabNavigationState {
  return { url, breadcrumbStack: stack };
}

function documentsState(): TabNavigationState {
  return state("/documents", [leaf("documents", "Documents", "/documents")]);
}

function settingsState(section: "general" | "about"): TabNavigationState {
  const url = `/settings/${section}`;
  return state(url, [leaf("settings", section === "general" ? "General" : "About", url)]);
}

function workspaceAgentsState(workspaceId = "workspace-a"): TabNavigationState {
  const url = `/workspace/${workspaceId}/agent`;
  return state(url, [
    leaf("workspace", "Workspace A", `/workspace/${workspaceId}`, { workspaceId }),
    leaf("workspace-section:agent", "Agents", url, { workspaceId, section: "agent" }),
  ]);
}

function agentDetailState(workspaceId = "workspace-a", agentId = "agent-a"): TabNavigationState {
  const url = `/workspace/${workspaceId}/agent/${agentId}`;
  return state(url, [
    ...workspaceAgentsState(workspaceId).breadcrumbStack,
    leaf("workspace-agent", "Personal Assistant", url, { workspaceId, agentId }),
  ]);
}

function makeTab(partial: {
  id: string;
  pinned?: boolean;
  historyIndex?: number;
  navigationHistory?: TabNavigationState[];
  viewMode?: PageTab["viewMode"];
}): PageTab {
  return {
    id: partial.id,
    pinned: partial.pinned ?? false,
    historyIndex: partial.historyIndex ?? 0,
    navigationHistory: partial.navigationHistory ?? [documentsState()],
    viewMode: partial.viewMode,
  };
}

function makeClosedSnapshot(tab: PageTab, originIndex: number): ClosedTabSnapshot {
  return {
    tab,
    originIndex,
    closedAt: Date.now(),
  };
}

function expectNoRemovedPageTabFields(tab: PageTab) {
  for (const field of FORBIDDEN_PAGE_TAB_FIELDS) {
    expect(tab).not.toHaveProperty(field);
  }
}

function mergePersisted(input: {
  tabs?: unknown[];
  activeTabId?: string | null;
  recentlyClosedTabs?: unknown[];
}) {
  return mergePersistedTabState(
    {
      tabs: input.tabs as PageTab[] | undefined,
      activeTabId: input.activeTabId ?? null,
      recentlyClosedTabs: input.recentlyClosedTabs as ClosedTabSnapshot[] | undefined,
    },
    {
      tabs: [],
      activeTabId: null,
      recentlyClosedTabs: [],
    }
  );
}

describe("tab-store URL-based navigation state", () => {
  beforeEach(() => {
    useTabStore.setState({
      tabs: [],
      activeTabId: null,
      recentlyClosedTabs: [],
    });
  });

  it("uses a new persisted storage key and ignores the old tab store key", () => {
    expect(TAB_STORE_STORAGE_KEY).toBe("viben-tab-store-v2");
    expect(TAB_STORE_STORAGE_KEY).not.toBe("viben-tab-store");
  });

  it("does not define a legacy persisted storage key", () => {
    expect(TAB_STORE_STORAGE_KEY).not.toBe("viben-tab-store");
  });

  it("merges v2 persisted state and drops invalid new-structure tabs without reading legacy fields", () => {
    const validTab = makeTab({
      id: "tab-valid",
      pinned: true,
      historyIndex: 5,
      navigationHistory: [workspaceAgentsState(), agentDetailState()],
      viewMode: "skill",
    });
    const invalidLegacyTab = {
      id: "tab-legacy",
      pinned: false,
      historyIndex: 0,
      history: ["/workspace/workspace-a/agent"],
      label: "Legacy",
    };
    const snapshotTab = makeTab({
      id: "tab-closed",
      navigationHistory: [settingsState("about")],
      viewMode: "page",
    });

    const result = mergePersisted({
      tabs: [validTab, invalidLegacyTab],
      activeTabId: "missing-tab",
      recentlyClosedTabs: [
        makeClosedSnapshot(snapshotTab, 4),
        { tab: invalidLegacyTab, originIndex: 1, closedAt: Date.now() },
      ],
    });

    expect(result.tabs).toHaveLength(1);
    expect(result.tabs[0]).toMatchObject({
      id: "tab-valid",
      pinned: true,
      historyIndex: 1,
      viewMode: "skill",
    });
    expect(result.tabs[0].navigationHistory).toEqual([
      workspaceAgentsState(),
      agentDetailState(),
    ]);
    expect(result.activeTabId).toBe("tab-valid");
    expectNoRemovedPageTabFields(result.tabs[0]);

    expect(result.recentlyClosedTabs).toHaveLength(1);
    expect(result.recentlyClosedTabs[0].tab.id).toBe("tab-closed");
    expect(result.recentlyClosedTabs[0].originIndex).toBe(4);
    expectNoRemovedPageTabFields(result.recentlyClosedTabs[0].tab);
  });

  it("partializes only the new PageTab shape", () => {
    const openedId = useTabStore.getState().openTab({
      navigationState: agentDetailState(),
      pinned: true,
      viewMode: "page",
    });

    const storeState = useTabStore.getState();
    const persisted = {
      tabs: storeState.tabs,
      activeTabId: storeState.activeTabId,
      recentlyClosedTabs: storeState.recentlyClosedTabs,
    };

    expect(persisted.activeTabId).toBe(openedId);
    expect(persisted.tabs).toHaveLength(1);
    expect(Object.keys(persisted.tabs[0]).sort()).toEqual([
      "historyIndex",
      "id",
      "navigationHistory",
      "pinned",
      "viewMode",
    ]);
    expectNoRemovedPageTabFields(persisted.tabs[0]);
  });

  it("PageTab fixtures only contain tab container fields and navigation history", () => {
    const tab = makeTab({ id: "tab-a" });

    expect(Object.keys(tab).sort()).toEqual([
      "historyIndex",
      "id",
      "navigationHistory",
      "pinned",
      "viewMode",
    ]);
    expectNoRemovedPageTabFields(tab);
  });

  it("opens a tab from navigationState without persisting breadcrumb leaf fields on PageTab", () => {
    const openedId = useTabStore.getState().openTab({
      navigationState: workspaceAgentsState(),
      pinned: false,
    });

    const opened = useTabStore.getState().tabs.find((tab) => tab.id === openedId);
    expect(opened).toBeTruthy();
    expect(opened?.navigationHistory).toEqual([workspaceAgentsState()]);
    expect(opened?.historyIndex).toBe(0);
    expect(opened).toBeDefined();
    expectNoRemovedPageTabFields(opened!);
  });

  it("duplicates a tab with the same navigation history and no removed fields", () => {
    const original = makeTab({
      id: "tab-a",
      pinned: true,
      historyIndex: 1,
      navigationHistory: [documentsState(), settingsState("general")],
      viewMode: "skill",
    });

    useTabStore.setState({
      tabs: [original],
      activeTabId: original.id,
      recentlyClosedTabs: [],
    });

    const duplicatedId = useTabStore.getState().duplicateTab(original.id);
    const duplicated = useTabStore.getState().tabs.find((tab) => tab.id === duplicatedId);

    expect(duplicatedId).toBeTruthy();
    expect(duplicated?.id).not.toBe(original.id);
    expect(duplicated?.historyIndex).toBe(original.historyIndex);
    expect(duplicated?.navigationHistory).toEqual(original.navigationHistory);
    expect(duplicated?.viewMode).toBe("skill");
    expect(duplicated?.pinned).toBe(false);
    expect(useTabStore.getState().activeTabId).toBe(duplicatedId);
    expect(useTabStore.getState().tabs.map((tab) => tab.id)).toEqual([
      original.id,
      duplicatedId,
    ]);
    expect(duplicated).toBeDefined();
    expectNoRemovedPageTabFields(duplicated!);
  });

  it("returns null and leaves state unchanged when duplicating an unknown tab", () => {
    const tab = makeTab({ id: "tab-a" });
